(function () {
if (typeof config.username !== 'string') throw new Error('必须配置字符串 username');
var username = config.username.trim().replace(/^instagram:/i, '').replace(/^@/, '');
if (/^https:\/\//i.test(username)) {
  var profile = /^https:\/\/(?:www\.|m\.)?instagram\.com\/([A-Za-z0-9._]{1,30})\/?(?:[?#].*)?$/i.exec(username);
  if (!profile) throw new Error('请填写 Instagram 用户名或有效的 HTTPS 主页链接');
  username = profile[1];
}
username = username.toLowerCase();
if (!/^[a-z0-9._]{1,30}$/.test(username) || ['p', 'reel', 'reels', 'tv', 'accounts', 'explore', 'direct', 'stories', 'about', 'developer', 'legal'].indexOf(username) >= 0) throw new Error('请填写有效的 Instagram 用户名，不是昵称或帖子链接');
return {username: username};
})()

(function () {
var response = output.fetch_list.list_response;
if (!response || response.platform !== 'instagram' || response.scope !== 'posts' || !Array.isArray(response.list)) throw new Error('Instagram 帖子列表节点未返回有效数据');
if (typeof response.next_marker !== 'string') throw new Error('Instagram 分页游标必须为字符串');
if (!(global.max_pages > 0) || Math.floor(global.max_pages) !== global.max_pages || !(global.max_posts > 0) || Math.floor(global.max_posts) !== global.max_posts) throw new Error('max_pages 和 max_posts 必须为正整数');
var items = [], seen = JSON.parse(JSON.stringify(global.scan_state.seen_ids));
for (var i = 0; i < response.list.length; i++) {
  var content = response.list[i];
  if (!content || (content.type !== 'video' && content.type !== 'album')) continue;
  var oid = content.external_id;
  if (typeof oid !== 'string' || !/^[0-9]+$/.test(oid)) throw new Error('Instagram 帖子 ID 必须为数字字符串');
  if (content.platform_id !== 'instagram' || content.id !== 'instagram:' + oid) throw new Error('Instagram 列表帖子的平台或内容 ID 不匹配');
  var url = String(content.source_url || content.url || '').trim();
  var match = /^https:\/\/(?:www\.|m\.)?instagram\.com\/(?:p|reel|tv)\/([A-Za-z0-9_-]+)\/?(?:[?#].*)?$/i.exec(url);
  if (!match || (content.external_id2 && content.external_id2 !== match[1])) throw new Error('Instagram 列表帖子缺少匹配的来源链接');
  if (Object.prototype.hasOwnProperty.call(seen, oid)) continue;
  seen[oid] = content.type;
  items.push({oid: oid, title: String(content.title || ''), type: content.type, url: url, shortcode: match[1]});
}
if (Object.keys(seen).length > global.max_posts) throw new Error('超过 max_posts，本次同步未完成');
return {seen_ids: seen, next_cursor: response.next_marker, items: items, content_ids: items.map(function (item) { return 'instagram:' + item.oid; })};
})()

(function () {
var items = output.parse_posts.page.items;
var response = output.check_posts.checks;
if (!response || !Array.isArray(response.list) || response.total !== items.length || response.list.length !== items.length) throw new Error('批量帖子存在性检查结果不完整');
var checks = Object.create(null);
response.list.forEach(function (check) {
  if (!check || typeof check.content_id !== 'string' || Object.prototype.hasOwnProperty.call(checks, check.content_id) || typeof check.exists !== 'boolean' || typeof check.task_count !== 'number' || !isFinite(check.task_count) || check.task_count < 0 || Math.floor(check.task_count) !== check.task_count || check.exists !== (check.task_count > 0)) throw new Error('批量帖子存在性检查结果无效');
  checks[check.content_id] = check;
});
var pending = [], skipped = 0;
for (var i = 0; i < items.length; i++) {
  var item = items[i], content_id = 'instagram:' + item.oid;
  if (!Object.prototype.hasOwnProperty.call(checks, content_id)) throw new Error('批量检查缺少帖子 ' + item.oid);
  if (checks[content_id].exists) skipped += 1;
  else pending.push(item);
}
return {pending: pending, skipped: skipped};
})()

(function () {
var detail = output.fetch_detail.detail_response;
if (!detail || detail.platform !== 'instagram' || !detail.content || detail.content.id !== 'instagram:' + input.item.oid) throw new Error('Instagram 详情与待下载帖子不匹配');
var result = detail.result;
if (!result || result.external_id !== input.item.oid || result.shortcode !== input.item.shortcode || !Array.isArray(result.media) || !result.media.length) throw new Error('Instagram 详情缺少匹配的媒体数据');
return result;
})()

(function () {
var result = output.download.download_result;
if (!result || (result.created !== true && result.skipped !== true)) throw new Error('下载工具没有返回已创建或已跳过结果');
return {oid: input.item.oid, created: result.created === true, skipped: result.skipped === true};
})()

(function () {
var items = output.parse_posts.page.items;
var selection = output.select_missing.selection;
var results = output.download_missing.downloads;
if (!Array.isArray(results) || results.length !== selection.pending.length) throw new Error('下载遍历结果不完整');
var submitted = 0, skipped = selection.skipped;
for (var i = 0; i < results.length; i++) {
  var result = results[i].output.inspect.download_status;
  if (result.oid !== selection.pending[i].oid) throw new Error('下载遍历结果与帖子不匹配');
  if (result.skipped) skipped += 1;
  else if (result.created) submitted += 1;
  else throw new Error('下载任务未创建');
}
var state = JSON.parse(JSON.stringify(global.scan_state));
state.pages += 1;
state.seen_ids = output.parse_posts.page.seen_ids;
state.checked += items.length;
state.submitted += submitted;
state.skipped += skipped;
state.cursor = output.parse_posts.page.next_cursor;
if (state.cursor) {
  if (state.visited_cursors.indexOf(state.cursor) >= 0) throw new Error('Instagram 分页游标重复，本次同步未完成');
  if (state.pages >= global.max_pages) throw new Error('达到 max_pages，本次同步未完成');
  state.visited_cursors.push(state.cursor);
}
return state;
})()

(function () {
var state = global.scan_state, ids = Object.keys(state.seen_ids);
return {platform: 'instagram', username: output.validate.creator.username, pages: state.pages, works: ids.length, videos: ids.filter(function (id) { return state.seen_ids[id] === 'video'; }).length, albums: ids.filter(function (id) { return state.seen_ids[id] === 'album'; }).length, checked: state.checked, submitted: state.submitted, skipped: state.skipped, stop_reason: 'no_more_pages', note: '已按平台返回的游标检查全部可访问页面；已有下载任务即跳过；submitted 表示任务已启动，不表示文件已下载完成'};
})()
